    50	export class PgLeaveRequestRepository implements ILeaveRequestRepository {
    51	  async findById(id: string): Promise<LeaveRequest | null> {
    52	    const result = await pool.query<LeaveRequestRow>(
    53	      'SELECT * FROM leave_requests WHERE id = $1',
    54	      [id],
    55	    );
    56	    if (result.rows.length === 0) {
    57	      return null;
    58	    }
    59	    return mapRowToLeaveRequest(result.rows[0]);
    60	  }
    61	
    62	  async findByEmployeeId(employeeId: string): Promise<LeaveRequest[]> {
    63	    const result = await pool.query<LeaveRequestRow>(
    64	      'SELECT * FROM leave_requests WHERE employee_id = $1 ORDER BY created_at DESC',
    65	      [employeeId],
    66	    );
