   115	  async update(
   116	    id: string,
   117	    data: Partial<LeaveRequest>,
   118	  ): Promise<LeaveRequest | null> {
   119	    const keys = Object.keys(data).filter(
   120	      (k) =>
   121	        data[k as keyof typeof data] !== undefined &&
   122	        COLUMN_MAP[k] !== undefined,
   123	    );
   124	
   125	    if (keys.length === 0) {
