   133	    const values = keys.map((key) => data[key as keyof typeof data]);
   134	
   135	    const result = await pool.query<LeaveRequestRow>(
   136	      `UPDATE leave_requests SET ${setClauses.join(', ')}, updated_at = NOW() WHERE id = $1 RETURNING *`,
   137	      [id, ...values],
